import csv

def answer() -> int:
    products = {}
    products_by_ean = {}
    with open('/app/dataset/product_catalog.csv') as f:
        reader = csv.DictReader(f)
        for row in reader:
            pid = row['product_id']
            ean = row['ean_code'].strip()
            price_str = row['unit_price'].replace(',', '.')
            products[pid] = {
                'unit_price': float(price_str),
                'storage_category': row['storage_category'].strip(),
                'max_safe_temp_c': float(row['max_safe_temp_c'])
            }
            products_by_ean[ean] = products[pid]

    # Find temperature anomalies
    max_safe_temp_by_zone = {}
    for pid, p in products.items():
        zone = p['storage_category']
        if zone not in max_safe_temp_by_zone:
            max_safe_temp_by_zone[zone] = p['max_safe_temp_c']

    temp_logs = []
    with open('/app/dataset/temperature_logs.csv') as f:
        reader = csv.DictReader(f)
        for row in reader:
            zone = row['zone'].strip()
            temp_str = row['temperature_c'].replace(',', '.')
            temp = float(temp_str)
            ts = row['timestamp']
            temp_logs.append({'ts': ts, 'zone': zone, 'temp': temp})

    # Normalize zone names (case-insensitive matching)
    zone_normalized = {}
    for z in max_safe_temp_by_zone:
        zone_normalized[z.lower()] = z

    # Find zones and times where temperature exceeds safe limit
    anomalous_periods = {}
    for entry in temp_logs:
        zone_lower = entry['zone'].lower()
        if zone_lower in zone_normalized:
            canonical_zone = zone_normalized[zone_lower]
            max_safe = max_safe_temp_by_zone[canonical_zone]
            if entry['temp'] > max_safe:
                day = entry['ts'].split(' ')[0]
                if day not in anomalous_periods:
                    anomalous_periods[day] = set()
                anomalous_periods[day].add(canonical_zone)

    total_revenue = 0.0

    with open('/app/dataset/warehouse_dispatches.csv') as f:
        reader = csv.DictReader(f)
        for row in reader:
            dispatch_id = int(row['dispatch_id'])
            pid = row['product_id']
            qty = int(row['quantity'])
            ts = row['timestamp']
            day = ts.split(' ')[0]

            if pid in products:
                prod = products[pid]
            elif pid in products_by_ean:
                prod = products_by_ean[pid]
            else:
                continue

            cat = prod['storage_category']

            # Check if this dispatch falls in an anomalous period for its zone
            is_disposal = False
            if day in anomalous_periods and cat in anomalous_periods[day]:
                # This is a disposal - don't count as revenue
                is_disposal = True

            if not is_disposal:
                total_revenue += qty * prod['unit_price']

    return int(total_revenue)


if __name__ == '__main__':
    import json
    with open('/app/answer.json', 'w') as f:
        json.dump(answer(), f, default=list)

